SET QUOTED_IDENTIFIER ON;
USE LibraryManagement;
GO
IF OBJECT_ID(N'dbo.Genres',N'U') IS NULL CREATE TABLE Genres(GenreId int IDENTITY PRIMARY KEY,Name nvarchar(100) NOT NULL UNIQUE,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID(N'dbo.Publishers',N'U') IS NULL CREATE TABLE Publishers(PublisherId int IDENTITY PRIMARY KEY,Name nvarchar(200) NOT NULL UNIQUE);
IF OBJECT_ID(N'dbo.Authors',N'U') IS NULL CREATE TABLE Authors(AuthorId int IDENTITY PRIMARY KEY,FullName nvarchar(200) NOT NULL);
IF OBJECT_ID(N'dbo.BookTitles',N'U') IS NULL CREATE TABLE BookTitles(BookId int IDENTITY PRIMARY KEY,Title nvarchar(300) NOT NULL,ISBN nvarchar(20) NULL,PublishedYear int NULL,Description nvarchar(max) NULL,GenreId int NULL REFERENCES Genres(GenreId),PublisherId int NULL REFERENCES Publishers(PublisherId),IsActive bit NOT NULL DEFAULT 1,CONSTRAINT CK_Book_Year CHECK(PublishedYear IS NULL OR PublishedYear BETWEEN 1400 AND 2100));
IF OBJECT_ID(N'dbo.BookAuthors',N'U') IS NULL CREATE TABLE BookAuthors(BookId int NOT NULL REFERENCES BookTitles(BookId),AuthorId int NOT NULL REFERENCES Authors(AuthorId),CONSTRAINT PK_BookAuthors PRIMARY KEY(BookId,AuthorId));
IF OBJECT_ID(N'dbo.BookCopies',N'U') IS NULL CREATE TABLE BookCopies(CopyId int IDENTITY PRIMARY KEY,CopyCode nvarchar(40) NOT NULL UNIQUE,BookId int NOT NULL REFERENCES BookTitles(BookId),ShelfLocation nvarchar(80) NULL,AcquiredAt date NULL,Status varchar(20) NOT NULL DEFAULT 'Available',CONSTRAINT CK_Copy_Status CHECK(Status IN('Available','Borrowed','Reserved','Damaged','Lost','Retired')));
IF OBJECT_ID(N'dbo.Readers',N'U') IS NULL CREATE TABLE Readers(ReaderId int IDENTITY PRIMARY KEY,ReaderCode nvarchar(30) NOT NULL UNIQUE,CardNumber nvarchar(30) NOT NULL UNIQUE,FullName nvarchar(200) NOT NULL,Email nvarchar(254) NULL,Phone nvarchar(30) NULL,RegisteredAt date NOT NULL,ExpiryDate date NOT NULL,Status varchar(20) NOT NULL DEFAULT 'Active',CONSTRAINT CK_Reader_Dates CHECK(ExpiryDate>=RegisteredAt));
IF OBJECT_ID(N'dbo.Loans',N'U') IS NULL CREATE TABLE Loans(LoanId int IDENTITY PRIMARY KEY,LoanCode nvarchar(40) NOT NULL UNIQUE,ReaderId int NOT NULL REFERENCES Readers(ReaderId),StaffUsername nvarchar(80) NOT NULL,LoanDate datetime2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID(N'dbo.LoanDetails',N'U') IS NULL CREATE TABLE LoanDetails(LoanDetailId int IDENTITY PRIMARY KEY,LoanId int NOT NULL REFERENCES Loans(LoanId),CopyId int NOT NULL REFERENCES BookCopies(CopyId),DueDate date NOT NULL,ReturnedAt datetime2 NULL,CONSTRAINT UQ_Loan_Copy UNIQUE(LoanId,CopyId));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'UX_OpenLoan_Copy' AND object_id=OBJECT_ID(N'dbo.LoanDetails')) CREATE UNIQUE INDEX UX_OpenLoan_Copy ON LoanDetails(CopyId) WHERE ReturnedAt IS NULL;
IF OBJECT_ID(N'dbo.Returns',N'U') IS NULL CREATE TABLE Returns(ReturnId int IDENTITY PRIMARY KEY,LoanDetailId int NOT NULL UNIQUE REFERENCES LoanDetails(LoanDetailId),ReturnedAt datetime2 NOT NULL DEFAULT SYSDATETIME(),Condition varchar(20) NOT NULL,OverdueDays int NOT NULL DEFAULT 0,FineAmount decimal(12,2) NOT NULL DEFAULT 0,WaiverReason nvarchar(300) NULL,StaffUsername nvarchar(80) NOT NULL,CONSTRAINT CK_Return_Fine CHECK(OverdueDays>=0 AND FineAmount>=0));
IF OBJECT_ID(N'dbo.FinePayments',N'U') IS NULL CREATE TABLE FinePayments(PaymentId int IDENTITY PRIMARY KEY,ReturnId int NOT NULL REFERENCES Returns(ReturnId),Amount decimal(12,2) NOT NULL CHECK(Amount>0),PaidAt datetime2 NOT NULL DEFAULT SYSDATETIME(),StaffUsername nvarchar(80) NOT NULL);
IF OBJECT_ID(N'dbo.Reservations',N'U') IS NULL CREATE TABLE Reservations(ReservationId int IDENTITY PRIMARY KEY,ReaderId int NOT NULL REFERENCES Readers(ReaderId),BookId int NOT NULL REFERENCES BookTitles(BookId),RequestedAt datetime2 NOT NULL DEFAULT SYSDATETIME(),Status varchar(20) NOT NULL DEFAULT 'Pending',HoldUntil datetime2 NULL);
IF OBJECT_ID(N'dbo.Accounts',N'U') IS NULL CREATE TABLE Accounts(AccountId int IDENTITY PRIMARY KEY,Username nvarchar(80) NOT NULL UNIQUE,PasswordHash nvarchar(500) NOT NULL,Role varchar(20) NOT NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID(N'dbo.Settings',N'U') IS NULL CREATE TABLE Settings([Key] nvarchar(80) PRIMARY KEY,Value nvarchar(200) NOT NULL);
IF OBJECT_ID(N'dbo.AuditLogs',N'U') IS NULL CREATE TABLE AuditLogs(AuditId bigint IDENTITY PRIMARY KEY,Username nvarchar(80) NOT NULL,Action nvarchar(100) NOT NULL,Entity nvarchar(100) NULL,EntityId nvarchar(80) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSDATETIME());
GO
-- Filtered unique index and serializable application transaction protect concurrent checkout.
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'IX_Book_Title' AND object_id=OBJECT_ID(N'dbo.BookTitles')) CREATE INDEX IX_Book_Title ON BookTitles(Title); IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'IX_Book_ISBN' AND object_id=OBJECT_ID(N'dbo.BookTitles')) CREATE INDEX IX_Book_ISBN ON BookTitles(ISBN); IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'IX_Copy_Book_Status' AND object_id=OBJECT_ID(N'dbo.BookCopies')) CREATE INDEX IX_Copy_Book_Status ON BookCopies(BookId,Status); IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'IX_LoanDetails_DueDate' AND object_id=OBJECT_ID(N'dbo.LoanDetails')) CREATE INDEX IX_LoanDetails_DueDate ON LoanDetails(DueDate);
